39	      <div className="layout">
40	        <aside className="sidebar">
41	          <RulesPanel rules={rules} onChange={loadRules} />
42	          <DocumentsPanel
43	            documents={documents}
44	            selectedId={selectedId}
45	            onSelect={setSelectedId}
46	            onChange={loadDocuments}
