79	import type { DocumentFull, DocumentSummary, Report, Rule, RuleInput, RuleType } from "./types";
80	
81	const BASE = "/api";
82	
83	export class ApiError extends Error {
84	  constructor(
85	    public status: number,
86	    message: string,
87	  ) {
88	    super(message);
89	  }
90	}
91	
92	async function send(path: string, init?: RequestInit): Promise<Response> {
93	  const res = await fetch(BASE + path, init);
94	  if (!res.ok) {
95	    let message = res.statusText;
96	    try {
97	      const body = (await res.json()) as { detail?: unknown };
98	      message = typeof body.detail === "string" ? body.detail : JSON.stringify(body.detail);
99	    } catch {
100	      /* non-JSON error body */
101	    }
102	    throw new ApiError(res.status, message);
103	  }
104	  return res;
105	}
106	
107	async function request<T>(path: string, init?: RequestInit): Promise<T> {
108	  const res = await send(path, init);
109	  return (await res.json()) as T;
110	}
111	
112	async function requestNoContent(path: string, init?: RequestInit): Promise<void> {
113	  await send(path, init);
114	}
115	
116	const json = (method: string, body: unknown): RequestInit => ({
117	  method,
118	  headers: { "Content-Type": "application/json" },
119	  body: JSON.stringify(body),
120	});
121	
122	export const api = {
123	  ruleTypes: () => request<RuleType[]>("/rules/types"),
124	  rules: () => request<Rule[]>("/rules"),
125	  createRule: (rule: RuleInput) => request<Rule>("/rules", json("POST", rule)),
126	  updateRule: (id: number, changes: Partial<RuleInput>) => request<Rule>(`/rules/${id}`, json("PATCH", changes)),
127	  deleteRule: (id: number) => requestNoContent(`/rules/${id}`, { method: "DELETE" }),
128	
129	  documents: () => request<DocumentSummary[]>("/documents"),
130	  document: (id: number) => request<DocumentFull>(`/documents/${id}`),
131	  uploadDocument: (file: File) => {
132	    const form = new FormData();
133	    form.append("file", file);
134	    return request<DocumentFull>("/documents", { method: "POST", body: form });
135	  },
136	  deleteDocument: (id: number) => requestNoContent(`/documents/${id}`, { method: "DELETE" }),
137	  check: (id: number) => request<Report>(`/documents/${id}/check`, json("POST", {})),
138	  latestReport: (id: number) => request<Report>(`/documents/${id}/report`),
139	};
