249	import { useCallback, useEffect, useState } from "react";
250	import { api, ApiError } from "../api";
251	import type { DocumentFull, Violation } from "../types";
252	
253	export interface DocumentReportState {
254	  document: DocumentFull | null;
255	  /** null => document not checked yet */
256	  violations: Violation[] | null;
257	  checkedAt: string | null;
258	  loading: boolean;
259	  checking: boolean;
260	  error: string | null;
261	}
262	
263	const EMPTY: DocumentReportState = {
264	  document: null,
265	  violations: null,
266	  checkedAt: null,
267	  loading: false,
268	  checking: false,
269	  error: null,
270	};
271	
272	/** Loads the latest report for a document (or the bare document if never checked) and runs checks. */
273	export function useDocumentReport(documentId: number | null) {
274	  const [state, setState] = useState<DocumentReportState>(EMPTY);
275	  const [loadedId, setLoadedId] = useState<number | null>(null);
276	
277	  // Reset during render when the selection changes (avoids setState inside an effect)
278	  if (loadedId !== documentId) {
279	    setLoadedId(documentId);
280	    setState({ ...EMPTY, loading: documentId !== null });
281	  }
282	
283	  useEffect(() => {
284	    if (documentId === null) return;
285	    let cancelled = false;
286	    load(documentId)
287	      .then((next) => !cancelled && setState({ ...EMPTY, ...next }))
288	      .catch((err: unknown) => !cancelled && setState({ ...EMPTY, error: errorMessage(err) }));
289	    return () => {
290	      cancelled = true;
291	    };
292	  }, [documentId]);
293	
294	  const runCheck = useCallback(async () => {
295	    if (documentId === null) return;
296	    setState((s) => ({ ...s, checking: true, error: null }));
297	    try {
298	      const report = await api.check(documentId);
299	      setState({
300	        ...EMPTY,
301	        document: report.document,
302	        violations: report.violations,
303	        checkedAt: report.checked_at,
304	      });
305	    } catch (err) {
306	      setState((s) => ({ ...s, checking: false, error: errorMessage(err) }));
307	    }
308	  }, [documentId]);
309	
310	  return { ...state, runCheck };
311	}
312	
313	async function load(documentId: number): Promise<Partial<DocumentReportState>> {
314	  try {
315	    const report = await api.latestReport(documentId);
316	    return { document: report.document, violations: report.violations, checkedAt: report.checked_at };
317	  } catch (err) {
318	    if (!(err instanceof ApiError && err.status === 404)) throw err;
319	    return { document: await api.document(documentId) };
320	  }
321	}
322	
323	export function errorMessage(err: unknown): string {
324	  return err instanceof Error ? err.message : String(err);
325	}
326	=== lib/highlight.ts
327	import type { Severity, Violation } from "../types";
328	
329	export const SEVERITY_RANK: Record<Severity, number> = { low: 0, medium: 1, high: 2 };
330	
331	/** A violation that points at a character range inside its block. */
332	export type SpanViolation = Violation & { start: number; end: number };
333	
334	export interface Segment {
335	  text: string;
336	  violations: SpanViolation[];
337	}
338	
339	export function hasSpan(v: Violation): v is SpanViolation {
340	  return v.start !== null && v.end !== null;
341	}
342	
343	export function worstSeverity(violations: readonly Violation[]): Severity {
344	  return violations.reduce<Severity>(
345	    (worst, v) => (SEVERITY_RANK[v.severity] > SEVERITY_RANK[worst] ? v.severity : worst),
346	    "low",
347	  );
348	}
349	
350	/**
351	 * Split text at every violation boundary so overlapping violations render correctly.
352	 * Each segment lists the violations that fully cover it. Offsets are clamped to the text.
353	 */
354	export function segmentText(text: string, violations: readonly Violation[]): Segment[] {
355	  const spans = violations.filter(hasSpan);
356	  const clamp = (n: number) => Math.max(0, Math.min(text.length, n));
357	  const cuts = new Set<number>([0, text.length]);
358	  for (const v of spans) {
359	    cuts.add(clamp(v.start));
360	    cuts.add(clamp(v.end));
361	  }
362	  const points = [...cuts].sort((a, b) => a - b);
363	
364	  const segments: Segment[] = [];
365	  for (let i = 0; i < points.length - 1; i++) {
366	    const [a, b] = [points[i], points[i + 1]];
367	    if (a === b) continue;
368	    segments.push({
369	      text: text.slice(a, b),
370	      violations: spans.filter((v) => clamp(v.start) <= a && clamp(v.end) >= b),
371	    });
372	  }
373	  return segments;
374	}
375	
376	/** Group violations by block; document-level ones (block_id null) are skipped. */
377	export function violationsByBlock(violations: readonly Violation[]): Map<number, Violation[]> {
378	  const map = new Map<number, Violation[]>();
379	  for (const v of violations) {
380	    if (v.block_id === null) continue;
381	    const list = map.get(v.block_id);
382	    if (list) list.push(v);
383	    else map.set(v.block_id, [v]);
384	  }
385	  return map;
386	}
387	
388	export function countBySeverity(violations: readonly Violation[]): Partial<Record<Severity, number>> {
389	  const counts: Partial<Record<Severity, number>> = {};
390	  for (const v of violations) counts[v.severity] = (counts[v.severity] ?? 0) + 1;
391	  return counts;
392	}
