394	import type { Block } from "../types";
395	
396	export interface TableLayout {
397	  kind: "table";
398	  tableIndex: number;
399	  rows: number;
400	  cols: number;
401	  /** cells[row][col] -> blocks in that cell (0-based) */
402	  cells: Block[][][];
403	}
404	
405	export type LayoutItem = { kind: "block"; block: Block } | TableLayout;
406	
407	/** Paragraphs/headings stay in order; consecutive table-cell blocks are grouped back into tables. */
408	export function layoutBlocks(blocks: readonly Block[]): LayoutItem[] {
409	  const items: LayoutItem[] = [];
410	  let i = 0;
411	  while (i < blocks.length) {
412	    const block = blocks[i];
413	    const tableIndex = block.table_index;
414	    if (tableIndex === null) {
415	      items.push({ kind: "block", block });
416	      i++;
417	      continue;
418	    }
419	    const tableBlocks: Block[] = [];
420	    while (i < blocks.length && blocks[i].table_index === tableIndex) tableBlocks.push(blocks[i++]);
421	    items.push(buildTable(tableIndex, tableBlocks));
422	  }
423	  return items;
424	}
425	
426	function buildTable(tableIndex: number, blocks: Block[]): TableLayout {
427	  const rows = Math.max(1, ...blocks.map((b) => b.row ?? 1));
428	  const cols = Math.max(1, ...blocks.map((b) => b.col ?? 1));
429	  const cells: Block[][][] = Array.from({ length: rows }, () => Array.from({ length: cols }, () => []));
430	  for (const b of blocks) cells[(b.row ?? 1) - 1][(b.col ?? 1) - 1].push(b);
431	  return { kind: "table", tableIndex, rows, cols, cells };
432	}
