440	  selectedId: number | null;
441	  onSelect: (id: number | null) => void;
442	  onChange: () => void;
443	}
444	
445	export default function DocumentsPanel({ documents, selectedId, onSelect, onChange }: Props) {
446	  const inputRef = useRef<HTMLInputElement>(null);
447	  const [uploading, setUploading] = useState(false);
448	  const [error, setError] = useState<string | null>(null);
449	
450	  async function upload(file: File) {
451	    setUploading(true);
452	    setError(null);
453	    try {
454	      const doc = await api.uploadDocument(file);
455	      onChange();
456	      onSelect(doc.id);
457	    } catch (err) {
458	      setError((err as Error).message);
459	    } finally {
460	      setUploading(false);
461	      if (inputRef.current) inputRef.current.value = "";
462	    }
463	  }
464	
465	  async function remove(doc: DocumentSummary) {
466	    await api.deleteDocument(doc.id);
467	    if (doc.id === selectedId) onSelect(null);
468	    onChange();
469	  }
470	
471	  return (
472	    <section className="panel">
473	      <div className="panel-header">
474	        <h2>Documents</h2>
475	        <button onClick={() => inputRef.current?.click()} disabled={uploading}>
476	          {uploading ? "Uploading…" : "Upload .docx"}
477	        </button>
478	        <input
479	          ref={inputRef}
480	          type="file"
481	          accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
482	          hidden
483	          onChange={(e) => e.target.files?.[0] && upload(e.target.files[0])}
484	        />
485	      </div>
486	      {error && <p className="error">{error}</p>}
487	      {!documents.length && <p className="muted">No documents uploaded yet.</p>}
488	      <ul className="list">
489	        {documents.map((doc) => (
490	          <li
491	            key={doc.id}
492	            className={`clickable ${doc.id === selectedId ? "selected" : ""}`}
493	            onClick={() => onSelect(doc.id)}
494	          >
495	            <div className="grow">
496	              <div dir="auto">{doc.filename}</div>
497	              <div className="muted small">
498	                {(doc.size_bytes / 1024).toFixed(0)} KB · {new Date(doc.uploaded_at).toLocaleString()}
499	              </div>
500	            </div>
501	            <button
502	              className="link danger"
503	              onClick={(e) => {
504	                e.stopPropagation();
505	                remove(doc);
506	              }}
507	            >
508	              Delete
509	            </button>
510	          </li>
511	        ))}
512	      </ul>
513	    </section>
514	  );
515	}
