596	import { createElement, useMemo, useRef, useState } from "react";
597	import { countBySeverity, hasSpan, segmentText, violationsByBlock, worstSeverity } from "../lib/highlight";
598	import { layoutBlocks } from "../lib/layout";
599	import { SEVERITIES, type Block, type DocumentFull, type Violation } from "../types";
600	
601	interface Props {
602	  document: DocumentFull;
603	  violations: Violation[] | null; // null => not checked yet
604	  checking: boolean;
605	  checkedAt: string | null;
606	  onCheck: () => void;
607	}
608	
609	/** Render with a `key` that changes per document/report, so the active selection resets. */
610	export default function ReportView({ document, violations, checking, checkedAt, onCheck }: Props) {
611	  const [activeId, setActiveId] = useState<string | null>(null);
612	  const blockRefs = useRef(new Map<number, HTMLElement>());
613	
614	  const byBlock = useMemo(() => violationsByBlock(violations ?? []), [violations]);
615	
616	  function focus(v: Violation) {
617	    setActiveId(v.id);
618	    if (v.block_id !== null) {
619	      blockRefs.current.get(v.block_id)?.scrollIntoView({ behavior: "smooth", block: "center" });
620	    }
621	  }
622	
623	  const registerBlock = (id: number) => (el: HTMLElement | null) => {
