export interface ViolationFilter {
  /** Severities to show; all three by default. */
  severities: ReadonlySet<Severity>;
  /** Show only this rule's violations; null => every rule. */
  ruleId: number | null;
}

export const ALL_SEVERITIES: ReadonlySet<Severity> = new Set(SEVERITIES);

export interface RuleOption {
  ruleId: number;
  ruleName: string;
  count: number;
}

export function isDocumentLevel(v: Violation): boolean {
  return v.block_id === null;
}

/** Document-level violations (block_id null) first; otherwise keep the server's order (block, then offset). */
export function documentLevelFirst(violations: readonly Violation[]): Violation[] {
  return [...violations.filter(isDocumentLevel), ...violations.filter((v) => !isDocumentLevel(v))];
}

export function filterViolations(violations: readonly Violation[], filter: ViolationFilter): Violation[] {
  return violations.filter(
    (v) => filter.severities.has(v.severity) && (filter.ruleId === null || v.rule_id === filter.ruleId),
  );
}

/** One option per rule that has violations, sorted by name, for the rule filter. */
export function ruleOptions(violations: readonly Violation[]): RuleOption[] {
  const byRule = new Map<number, RuleOption>();
  for (const v of violations) {
    const option = byRule.get(v.rule_id);
    if (option) option.count++;
    else byRule.set(v.rule_id, { ruleId: v.rule_id, ruleName: v.rule_name, count: 1 });
  }
  return [...byRule.values()].sort((a, b) => a.ruleName.localeCompare(b.ruleName) || a.ruleId - b.ruleId);
}

export function toggleSeverity(selected: ReadonlySet<Severity>, severity: Severity): Set<Severity> {
  const next = new Set(selected);
  if (next.has(severity)) next.delete(severity);
  else next.add(severity);
  return next;
}

import { describe, expect, it } from "vitest";
import { violation } from "../test/fixtures";
import {
  ALL_SEVERITIES,
  documentLevelFirst,
  filterViolations,
  ruleOptions,
  toggleSeverity,
} from "./violations";

const A = violation({ id: "1-0", rule_id: 1, rule_name: "Beta", block_id: 2 }, "high");
const B = violation({ id: "2-0", rule_id: 2, rule_name: "Alpha", block_id: 1 }, "low");
const DOC_LEVEL = violation({ id: "3-0", rule_id: 3, rule_name: "Gamma", block_id: null }, "medium");
const A2 = violation({ id: "1-1", rule_id: 1, rule_name: "Beta", block_id: 3 }, "medium");

describe("violations", () => {
  it("puts document-level violations first and keeps the rest in order", () => {
    expect(documentLevelFirst([A, B, DOC_LEVEL, A2]).map((v) => v.id)).toEqual(["3-0", "1-0", "2-0", "1-1"]);
  });

  it("filters by severity and rule", () => {
    const all = [A, B, DOC_LEVEL, A2];
    expect(filterViolations(all, { severities: ALL_SEVERITIES, ruleId: null })).toHaveLength(4);
    expect(filterViolations(all, { severities: new Set(["high", "medium"]), ruleId: null }).map((v) => v.id)).toEqual([
      "1-0",
      "3-0",
      "1-1",
    ]);
    expect(filterViolations(all, { severities: ALL_SEVERITIES, ruleId: 1 }).map((v) => v.id)).toEqual(["1-0", "1-1"]);
    expect(filterViolations(all, { severities: new Set(), ruleId: null })).toEqual([]);
  });

  it("lists rules with counts, sorted by name", () => {
    expect(ruleOptions([A, B, DOC_LEVEL, A2])).toEqual([
      { ruleId: 2, ruleName: "Alpha", count: 1 },
      { ruleId: 1, ruleName: "Beta", count: 2 },
      { ruleId: 3, ruleName: "Gamma", count: 1 },
    ]);
    expect(ruleOptions([])).toEqual([]);
  });

  it("toggles a severity without mutating the input", () => {
    const all = new Set(ALL_SEVERITIES);
    const next = toggleSeverity(all, "low");
    expect([...next].sort()).toEqual(["high", "medium"]);
    expect(all.has("low")).toBe(true);
    expect(toggleSeverity(next, "low").has("low")).toBe(true);
  });
});

import type { RuleCreate, RuleTemplate, RuleTemplateCategory, SampleRulesResult } from "../types";

export const CATEGORY_LABEL: Record<RuleTemplateCategory, string> = {
  security: "Security",
  privacy: "Privacy",
  style: "Style",
  structure: "Structure",
  ai: "AI",
};

const CATEGORY_ORDER: readonly RuleTemplateCategory[] = ["security", "privacy", "style", "structure", "ai"];

export interface TemplateGroup {
  category: RuleTemplateCategory;
  label: string;
  templates: RuleTemplate[];
}

/** Templates grouped by category in a fixed order; empty groups are dropped. Unknown categories go last. */
export function groupTemplates(templates: readonly RuleTemplate[]): TemplateGroup[] {
  const known = CATEGORY_ORDER.map((category) => ({
    category,
    label: CATEGORY_LABEL[category],
    templates: templates.filter((t) => t.category === category),
  }));
  const unknown = templates.filter((t) => !CATEGORY_ORDER.includes(t.category));
  const groups = unknown.length
    ? [...known, { category: "structure" as const, label: "Other", templates: unknown }]
    : known;
  return groups.filter((g) => g.templates.length > 0);
}

/** A copy of the template's rule to prefill the new-rule form (the template itself is never mutated). */
export function draftFromTemplate(template: RuleTemplate): RuleCreate {
  const { rule } = template;
  return { ...rule, params: structuredClone(rule.params) };
}

export function sampleResultMessage(result: SampleRulesResult): string {
  return `${result.created.length} added, ${result.skipped.length} already present`;
}

/** Rules of this type are checked by the LLM and spend AI quota. */
export const LLM_RULE_TYPE = "llm";

export function usesAiQuota(rule: { type: string }): boolean {
  return rule.type === LLM_RULE_TYPE;
}

