import { useCallback, useEffect, useState } from "react";
import { api } from "../api";
import { errorMessage } from "../lib/errors";
import type { Rule, RuleCreate, RuleType, RuleUpdate } from "../types";

export interface RulesState {
  rules: Rule[];
  types: RuleType[];
  loading: boolean;
  error: string | null;
}

/**
 * Rules and rule types, plus CRUD. `createRule` / `updateRule` re-throw so a form can show
 * the server's validation message; toggle and delete report failures through `error`.
 */
export function useRules() {
  const [state, setState] = useState<RulesState>({ rules: [], types: [], loading: true, error: null });

  useEffect(() => {
    let cancelled = false;
    Promise.all([api.rules(), api.ruleTypes()])
      .then(([rules, types]) => !cancelled && setState({ rules, types, loading: false, error: null }))
      .catch((err: unknown) => !cancelled && setState((s) => ({ ...s, loading: false, error: errorMessage(err) })));
    return () => {
      cancelled = true;
    };
  }, []);

  const reload = useCallback(async () => {
    try {
      const rules = await api.rules();
      setState((s) => ({ ...s, rules, error: null }));
    } catch (err) {
      setState((s) => ({ ...s, error: errorMessage(err) }));
    }
  }, []);

  const createRule = useCallback(
    async (input: RuleCreate) => {
      await api.createRule(input);
      await reload();
    },
    [reload],
  );

  const updateRule = useCallback(
    async (id: number, changes: RuleUpdate) => {
      await api.updateRule(id, changes);
      await reload();
    },
    [reload],
  );

  const guarded = useCallback(
    async (action: () => Promise<unknown>) => {
      try {
        await action();
        await reload();
      } catch (err) {
        setState((s) => ({ ...s, error: errorMessage(err) }));
      }
    },
    [reload],
  );

  const toggleRule = useCallback(
    (rule: Rule) => guarded(() => api.updateRule(rule.id, { enabled: !rule.enabled })),
    [guarded],
  );
  const deleteRule = useCallback((rule: Rule) => guarded(() => api.deleteRule(rule.id)), [guarded]);
  const dismissError = useCallback(() => setState((s) => ({ ...s, error: null })), []);

  return { ...state, reload, createRule, updateRule, toggleRule, deleteRule, dismissError };
}

import { useCallback, useEffect, useState } from "react";
import { api } from "../api";
import { errorMessage } from "../lib/errors";
import type { DocumentFull, DocumentSummary } from "../types";

export interface DocumentsState {
  documents: DocumentSummary[];
  loading: boolean;
  uploading: boolean;
  error: string | null;
}

/** Uploaded documents: list, upload and delete. Failures are reported through `error`. */
export function useDocuments() {
  const [state, setState] = useState<DocumentsState>({ documents: [], loading: true, uploading: false, error: null });

  useEffect(() => {
    let cancelled = false;
    api
      .documents()
      .then((documents) => !cancelled && setState((s) => ({ ...s, documents, loading: false })))
      .catch((err: unknown) => !cancelled && setState((s) => ({ ...s, loading: false, error: errorMessage(err) })));
    return () => {
      cancelled = true;
    };
  }, []);

  const reload = useCallback(async () => {
    try {
      const documents = await api.documents();
      setState((s) => ({ ...s, documents, error: null }));
    } catch (err) {
      setState((s) => ({ ...s, error: errorMessage(err) }));
    }
  }, []);

  /** Resolves to the uploaded document, or null when the upload failed. */
  const upload = useCallback(
    async (file: File): Promise<DocumentFull | null> => {
      setState((s) => ({ ...s, uploading: true, error: null }));
      try {
        const doc = await api.uploadDocument(file);
        setState((s) => ({ ...s, uploading: false }));
        await reload();
        return doc;
      } catch (err) {
        setState((s) => ({ ...s, uploading: false, error: errorMessage(err) }));
        return null;
      }
    },
    [reload],
  );

  /** Resolves to true when the document was deleted. */
  const remove = useCallback(
    async (id: number): Promise<boolean> => {
      try {
        await api.deleteDocument(id);
        await reload();
        return true;
      } catch (err) {
        setState((s) => ({ ...s, error: errorMessage(err) }));
        return false;
      }
    },
    [reload],
  );

  return { ...state, reload, upload, remove };
}

import { useCallback, useEffect, useState } from "react";
import { api, isMissingEndpoint } from "../api";
import { errorMessage } from "../lib/errors";
import { sampleResultMessage } from "../lib/templates";
import type { RuleTemplate } from "../types";

/** `unavailable` => this server has no template endpoints (404/405); the UI hides the template features. */
export type TemplatesStatus = "loading" | "ready" | "unavailable" | "error";

export interface TemplatesState {
  templates: RuleTemplate[];
  status: TemplatesStatus;
  error: string | null;
}

export interface SamplesState {
  loading: boolean;
  /** e.g. "3 added, 2 already present" */
  message: string | null;
  error: string | null;
}

export const SAMPLES_UNAVAILABLE = "Sample rules are not available on this server.";

/**
 * Rule templates (`GET /api/rules/templates`) and the sample set (`POST /api/rules/samples`).
 * `onRulesChanged` is called after samples were loaded so the rules list refreshes.
 */
export function useRuleTemplates(onRulesChanged: () => unknown) {
  const [state, setState] = useState<TemplatesState>({ templates: [], status: "loading", error: null });
  const [samples, setSamples] = useState<SamplesState>({ loading: false, message: null, error: null });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let cancelled = false;
    api
      .ruleTemplates()
      .then((templates) => !cancelled && setState({ templates, status: "ready", error: null }))
      .catch((err: unknown) => {
        if (cancelled) return;
        setState(
          isMissingEndpoint(err)
            ? { templates: [], status: "unavailable", error: null }
            : { templates: [], status: "error", error: errorMessage(err) },
        );
      });
    return () => {
      cancelled = true;
    };
  }, [attempt]);

  const retry = useCallback(() => {
    setState((s) => ({ ...s, status: "loading", error: null }));
    setAttempt((n) => n + 1);
  }, []);

  const loadSamples = useCallback(async () => {
    setSamples({ loading: true, message: null, error: null });
    try {
      const result = await api.loadSampleRules();
      setSamples({ loading: false, message: sampleResultMessage(result), error: null });
      await onRulesChanged();
    } catch (err) {
      setSamples({
        loading: false,
        message: null,
        error: isMissingEndpoint(err) ? SAMPLES_UNAVAILABLE : errorMessage(err),
      });
    }
  }, [onRulesChanged]);

  const dismissSamples = useCallback(() => setSamples({ loading: false, message: null, error: null }), []);

  return { ...state, retry, samples, loadSamples, dismissSamples };
}

import { useCallback, useMemo, useState } from "react";
import { countBySeverity } from "../lib/highlight";
import {
  ALL_SEVERITIES,
  documentLevelFirst,
  filterViolations,
  ruleOptions,
  toggleSeverity as toggle,
} from "../lib/violations";
import type { Severity, Violation } from "../types";

/**
 * Severity chips + rule filter over a report's violations.
 * Chip counts reflect the rule filter, so they always match what a chip would show.
 * Reset by giving the owning component a new `key` per report.
 */
export function useViolationFilters(violations: readonly Violation[]) {
  const [severities, setSeverities] = useState<ReadonlySet<Severity>>(ALL_SEVERITIES);
  const [ruleId, setRuleId] = useState<number | null>(null);

  const rules = useMemo(() => ruleOptions(violations), [violations]);
  // A stale rule filter (rule no longer in this report) behaves like "all rules"
  const effectiveRuleId = ruleId !== null && rules.some((r) => r.ruleId === ruleId) ? ruleId : null;

  const counts = useMemo(
    () => countBySeverity(filterViolations(violations, { severities: ALL_SEVERITIES, ruleId: effectiveRuleId })),
    [violations, effectiveRuleId],
  );
  const visible = useMemo(
    () => documentLevelFirst(filterViolations(violations, { severities, ruleId: effectiveRuleId })),
    [violations, severities, effectiveRuleId],
  );

  const toggleSeverity = useCallback((s: Severity) => setSeverities((current) => toggle(current, s)), []);
  const clear = useCallback(() => {
    setSeverities(ALL_SEVERITIES);
    setRuleId(null);
  }, []);

  const isFiltered = effectiveRuleId !== null || severities.size !== ALL_SEVERITIES.size;

  return { severities, toggleSeverity, ruleId: effectiveRuleId, setRuleId, rules, counts, visible, isFiltered, clear };
}

/** How long a paragraph flashes after its violation is clicked. Keep in sync with `--animate-flash` in styles.css. */
export const FLASH_MS = 1500;

export function prefersReducedMotion(): boolean {
  return typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function scrollBehavior(): ScrollBehavior {
  return prefersReducedMotion() ? "auto" : "smooth";
}

import { useCallback, useEffect, useRef, useState } from "react";
import { FLASH_MS, scrollBehavior } from "../lib/motion";
import type { Violation } from "../types";

export interface Flash {
  blockId: number;
  /** Changes on every click, so a keyed overlay remounts and the CSS animation restarts. */
  nonce: number;
}

/**
 * The selected ("active") violation and the paragraph flash.
 * - From the list: scroll the paragraph into view (smooth), mark it active and flash it for FLASH_MS.
 * - From the document (clicking a highlight): mark it active and scroll its card into view in the list.
 * Document-level violations (block_id null) only become active.
 */
export function useViolationFocus() {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [flash, setFlash] = useState<Flash | null>(null);
  const blocks = useRef(new Map<number, HTMLElement>());
  const items = useRef(new Map<string, HTMLElement>());
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const nonce = useRef(0);

  useEffect(() => () => clearTimeout(timer.current), []);

  const selectFromList = useCallback((v: Violation) => {
    setActiveId(v.id);
    if (v.block_id === null) return;
    const blockId = v.block_id;
    blocks.current.get(blockId)?.scrollIntoView({ behavior: scrollBehavior(), block: "center" });
    nonce.current += 1;
    setFlash({ blockId, nonce: nonce.current });
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setFlash(null), FLASH_MS);
  }, []);

  const selectFromDocument = useCallback((v: Violation) => {
    setActiveId(v.id);
    items.current.get(v.id)?.scrollIntoView({ behavior: scrollBehavior(), block: "nearest" });
  }, []);

  const registerBlock = useCallback(
    (id: number) => (el: HTMLElement | null) => {
      if (el) blocks.current.set(id, el);
      else blocks.current.delete(id);
    },
    [],
  );

  const registerItem = useCallback(
    (id: string) => (el: HTMLElement | null) => {
      if (el) items.current.set(id, el);
      else items.current.delete(id);
    },
    [],
  );

  return { activeId, flash, selectFromList, selectFromDocument, registerBlock, registerItem };
}

