import { createElement, type KeyboardEvent } from "react";
import type { Flash } from "../hooks/useViolationFocus";
import { hasSpan, segmentText, worstSeverity } from "../lib/highlight";
import { layoutBlocks } from "../lib/layout";
import { cx, SEVERITY_CLASSES } from "../lib/severity";
import type { Block, Violation } from "../types";

interface CommonProps {
  byBlock: Map<number, Violation[]>;
  activeId: string | null;
  flash: Flash | null;
  onPick: (v: Violation) => void;
  registerBlock: (id: number) => (el: HTMLElement | null) => void;
}

/** The document as paragraphs, headings and tables, with severity highlights. */
export default function DocumentPane({ blocks, ...props }: CommonProps & { blocks: Block[] }) {
  if (!blocks.length) return <p className="text-sm text-slate-600">This document has no text.</p>;
  return (
    <div className="flex flex-col gap-2">
      {layoutBlocks(blocks).map((item) =>
        item.kind === "block" ? (
          <BlockView key={item.block.id} block={item.block} {...props} />
        ) : (
          <div key={`t${item.tableIndex}`} className="my-2 overflow-x-auto">
            <table dir="auto" className="w-full border-collapse text-sm">
              <tbody>
                {item.cells.map((row, r) => (
                  <tr key={r}>
                    {row.map((cellBlocks, c) => (
                      <td key={c} className="border border-slate-300 bg-white/60 p-1.5 align-top">
                        {cellBlocks.map((b) => (
                          <BlockView key={b.id} block={b} {...props} />
                        ))}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ),
      )}
    </div>
  );
}

function tooltip(violations: readonly Violation[]): string {
  return violations.map((v) => `${v.rule_name}: ${v.message}`).join("\n");
}

type BlockTag = "p" | "h3" | "h4" | "h5" | "h6";

function headingTag(block: Block): BlockTag {
  if (block.kind !== "heading") return "p";
  const level = Math.min(Math.max(block.heading_level ?? 1, 1) + 2, 6);
  return `h${level}` as BlockTag;
}

function headingClass(block: Block): string {
  if (block.kind !== "heading") return "text-[0.95rem] leading-relaxed text-slate-800";
  const level = block.heading_level ?? 1;
  if (level === 0) return "text-2xl font-bold text-slate-950";
  if (level === 1) return "mt-3 text-xl font-semibold text-slate-950";
  if (level === 2) return "mt-2 text-lg font-semibold text-slate-900";
  return "mt-1 text-base font-semibold text-slate-900";
}

/** Enter / Space activate a focusable non-button element. */
function onActivate(action: () => void) {
  return (e: KeyboardEvent) => {
    if (e.key !== "Enter" && e.key !== " ") return;
    e.preventDefault();
    e.stopPropagation();
    action();
  };
}

function BlockView({ block, byBlock, activeId, flash, onPick, registerBlock }: CommonProps & { block: Block }) {
  const violations = byBlock.get(block.id) ?? [];
  // Violations without a span (quote not found, or a block-level rule) flag the whole block
  const wholeBlock = violations.filter((v) => !hasSpan(v));
  const flagged = wholeBlock.length > 0;
  const active = violations.some((v) => v.id === activeId);
  const flashing = flash?.blockId === block.id;
  const pickBlock = () => onPick(wholeBlock[0]);

  const children = block.text
    ? segmentText(block.text, violations).map((seg, i) => {
        if (!seg.violations.length) return <span key={i}>{seg.text}</span>;
        const severity = worstSeverity(seg.violations);
        const pick = () => onPick(seg.violations[0]);
        const segActive = seg.violations.some((v) => v.id === activeId);
        return (
          <mark
            key={i}
            data-violation={seg.violations.map((v) => v.id).join(" ")}
            data-severity={severity}
            data-active={segActive || undefined}
            role="button"
            tabIndex={0}
            className={cx(
              "rounded-sm px-0.5 text-slate-950 underline decoration-2 underline-offset-2",
              SEVERITY_CLASSES[severity].mark,
              segActive && "ring-2 ring-slate-900",
            )}
            title={tooltip(seg.violations)}
            onClick={(e) => {
              e.stopPropagation();
              pick();
            }}
            onKeyDown={onActivate(pick)}
          >
            {seg.text}
          </mark>
        );
      })
    : " ";

  const blockSeverity = flagged ? worstSeverity(wholeBlock) : null;

  return createElement(
    headingTag(block),
    {
      ref: registerBlock(block.id),
      dir: "auto",
      "data-block-id": block.id,
      "data-severity": blockSeverity ?? undefined,
      "data-active": active || undefined,
      "data-flash": flashing || undefined,
      role: flagged ? "button" : undefined,
      tabIndex: flagged ? 0 : undefined,
      className: cx(
        "relative scroll-my-24 rounded-lg px-2 py-1 transition-shadow",
        headingClass(block),
        blockSeverity && SEVERITY_CLASSES[blockSeverity].block,
        active && "ring-2 ring-sky-500 ring-offset-2 ring-offset-white",
      ),
      onClick: flagged ? pickBlock : undefined,
      onKeyDown: flagged ? onActivate(pickBlock) : undefined,
      title: flagged ? tooltip(wholeBlock) : undefined,
    },
    children,
    flashing && (
      <span
        key={flash.nonce}
        aria-hidden="true"
        data-testid="flash-overlay"
        className="pointer-events-none absolute inset-0 animate-flash rounded-lg motion-reduce:animate-none motion-reduce:bg-sky-300/30"
      />
    ),
  );
}

import { cx, SEVERITY_CLASSES, SEVERITY_LABEL } from "../lib/severity";
import { isDocumentLevel, type RuleOption } from "../lib/violations";
import { SEVERITIES, type Severity, type Violation } from "../types";
import { Button, SeverityBadge } from "./ui";

interface Props {
  /** Already filtered, document-level first. */
  violations: Violation[];
  total: number;
  severities: ReadonlySet<Severity>;
  counts: Partial<Record<Severity, number>>;
  onToggleSeverity: (s: Severity) => void;
  rules: RuleOption[];
  ruleId: number | null;
  onRuleChange: (ruleId: number | null) => void;
  isFiltered: boolean;
  onClearFilters: () => void;
  activeId: string | null;
  onPick: (v: Violation) => void;
  registerItem: (id: string) => (el: HTMLElement | null) => void;
}

export default function ViolationsPanel({
  violations,
  total,
  severities,
  counts,
  onToggleSeverity,
  rules,
  ruleId,
  onRuleChange,
  isFiltered,
  onClearFilters,
  activeId,
  onPick,
  registerItem,
}: Props) {
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-2" role="group" aria-label="Filter by severity">
        {SEVERITIES.map((s) => (
          <button
            key={s}
            type="button"
            aria-pressed={severities.has(s)}
            onClick={() => onToggleSeverity(s)}
            className={cx(
              "inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-semibold transition-colors",
              SEVERITY_CLASSES[s].chip,
            )}
          >
            {SEVERITY_LABEL[s]}
            <span className="tabular-nums">{counts[s] ?? 0}</span>
          </button>
        ))}
      </div>
      <label className="flex items-center gap-2 text-xs font-medium text-slate-700">
        Rule
        <select
          className="min-w-0 flex-1 rounded-full border border-slate-300 bg-white px-3 py-1.5 text-sm text-slate-900"
          value={ruleId ?? ""}
          onChange={(e) => onRuleChange(e.target.value === "" ? null : Number(e.target.value))}
          aria-label="Filter by rule"
        >
          <option value="">All rules ({total})</option>
          {rules.map((r) => (
            <option key={r.ruleId} value={r.ruleId}>
              {r.ruleName} ({r.count})
            </option>
          ))}
        </select>
      </label>

      {violations.length === 0 && isFiltered && (
        <div className="flex items-center justify-between gap-2 rounded-2xl bg-slate-100 px-3 py-2 text-sm text-slate-700">
          No violations match the filters.
          <Button variant="secondary" size="sm" onClick={onClearFilters}>
            Clear filters
          </Button>
        </div>
      )}

      <ul className="flex flex-col gap-2" aria-label="Violations list">
        {violations.map((v) => {
          const active = v.id === activeId;
          return (
            <li key={v.id}>
              <button
                ref={registerItem(v.id)}
                type="button"
                aria-current={active ? "true" : undefined}
                data-active={active || undefined}
                onClick={() => onPick(v)}
                className={cx(
                  "flex w-full flex-col gap-1 rounded-2xl border border-l-4 border-slate-200 bg-white/90 px-4 py-3 text-left text-sm shadow-sm transition hover:bg-white",
                  SEVERITY_CLASSES[v.severity].card,
                  active && "bg-white ring-2 ring-slate-900",
                )}
              >
                <span className="flex flex-wrap items-center gap-2">
                  <SeverityBadge severity={v.severity} />
                  <strong className="font-semibold text-slate-900" dir="auto">
                    {v.rule_name}
                  </strong>
                  {isDocumentLevel(v) && (
                    <span className="rounded-full bg-slate-900 px-2 py-0.5 text-[0.7rem] font-semibold text-white">
                      Whole document
                    </span>
                  )}
                </span>
                <span className="text-slate-800" dir="auto">
                  {v.message}
                </span>
                {v.excerpt && (
                  <span className="rounded-lg bg-slate-100 px-2 py-1 text-xs text-slate-700 italic" dir="auto">
                    {v.excerpt}
                  </span>
                )}
                {!isDocumentLevel(v) && (
                  <span className="text-xs text-slate-600" dir="auto">
                    {v.location}
                  </span>
                )}
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useMemo } from "react";
import { useViolationFilters } from "../hooks/useViolationFilters";
import { useViolationFocus } from "../hooks/useViolationFocus";
import { violationsByBlock } from "../lib/highlight";
import type { DocumentFull, Violation } from "../types";
import DocumentPane from "./DocumentPane";
import { AiQuotaBadge, Button, GlassPanel } from "./ui";
import ViolationsPanel from "./ViolationsPanel";

interface Props {
  document: DocumentFull;
  violations: Violation[] | null; // null => not checked yet
  checking: boolean;
  checkedAt: string | null;
  /** Enabled rules of type `llm`: a check will spend AI quota. */
  aiRulesEnabled: number;
  onCheck: () => void;
}

const NO_VIOLATIONS: Violation[] = [];

/** Split screen: document with highlights (left) and the violations list (right). Key it per document/report. */
export default function ReportView({ document, violations, checking, checkedAt, aiRulesEnabled, onCheck }: Props) {
  const filters = useViolationFilters(violations ?? NO_VIOLATIONS);
  const focus = useViolationFocus();
  const byBlock = useMemo(() => violationsByBlock(filters.visible), [filters.visible]);

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-4">
      <GlassPanel className="flex flex-wrap items-center gap-x-4 gap-y-2 px-5 py-3">
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-base font-semibold text-slate-900" dir="auto" title={document.filename}>
            {document.filename}
          </h2>
          <p className="text-xs text-slate-600">
            {checkedAt ? `Checked ${new Date(checkedAt).toLocaleString()}` : "Not checked yet"}
          </p>
        </div>
        {aiRulesEnabled > 0 && (
          <span className="flex items-center gap-2 text-xs text-slate-700">
            <AiQuotaBadge />
            {aiRulesEnabled} AI {aiRulesEnabled === 1 ? "rule" : "rules"} enabled
          </span>
        )}
        <Button onClick={onCheck} disabled={checking}>
          {checking ? "Checking…" : violations ? "Re-check" : "Check document"}
        </Button>
      </GlassPanel>

      <div className="grid min-h-0 flex-1 gap-4 lg:grid-cols-[minmax(0,3fr)_minmax(0,2fr)]">
        <GlassPanel as="article" aria-label="Document" className="min-h-0 p-6 lg:overflow-y-auto">
          <DocumentPane
            blocks={document.blocks}
            byBlock={byBlock}
            activeId={focus.activeId}
            flash={focus.flash}
            onPick={focus.selectFromDocument}
            registerBlock={focus.registerBlock}
          />
        </GlassPanel>

        <GlassPanel as="aside" aria-labelledby="violations-heading" className="flex min-h-0 flex-col gap-3 p-5 lg:overflow-y-auto">
          <h3 id="violations-heading" className="text-base font-semibold text-slate-900">
            Violations
            {violations && <span className="ml-2 text-sm font-normal text-slate-600">{violations.length} total</span>}
          </h3>
          {checking && (
            <p role="status" className="text-sm text-slate-600">
              Checking the document… AI rules can take a minute on long documents.
            </p>
          )}
          {!checking && violations === null && (
            <p className="text-sm text-slate-600">Not checked yet. Click “Check document”.</p>
          )}
          {!checking && violations?.length === 0 && (
            <p role="status" className="rounded-2xl bg-emerald-50 px-3 py-2 text-sm font-medium text-emerald-900 ring-1 ring-emerald-200">
              No violations found ✓
            </p>
          )}
          {violations && violations.length > 0 && (
            <ViolationsPanel
              violations={filters.visible}
              total={violations.length}
              severities={filters.severities}
              counts={filters.counts}
              onToggleSeverity={filters.toggleSeverity}
              rules={filters.rules}
              ruleId={filters.ruleId}
              onRuleChange={filters.setRuleId}
              isFiltered={filters.isFiltered}
              onClearFilters={filters.clear}
              activeId={focus.activeId}
              onPick={focus.selectFromList}
              registerItem={focus.registerItem}
            />
          )}
        </GlassPanel>
      </div>
    </div>
  );
}

import { cx, SEVERITY_CLASSES, SEVERITY_LABEL } from "../lib/severity";
import { SEVERITIES, type Severity } from "../types";
import { SeverityDot } from "./ui";

interface Props {
  documentName: string | null;
  /** null => no report for the selected document */
  counts: Partial<Record<Severity, number>> | null;
}

export default function TopBar({ documentName, counts }: Props) {
  return (
    <header className="flex flex-wrap items-center gap-x-6 gap-y-2 border-b border-white/10 bg-slate-950/60 px-4 py-3 backdrop-blur-md sm:px-6">
      <div className="flex items-baseline gap-3">
        <h1 className="text-lg font-bold tracking-tight text-white">Ruleguarder</h1>
        <span className="hidden text-sm text-slate-300 sm:inline">Check Word documents against your rules</span>
      </div>
      {documentName && (
        <p className="min-w-0 flex-1 truncate text-sm text-slate-200" dir="auto" title={documentName}>
          <span className="text-slate-400">Document: </span>
          {documentName}
        </p>
      )}
      {counts && (
        <ul className="ml-auto flex items-center gap-2" aria-label="Violations by severity">
          {SEVERITIES.map((s) => (
            <li
              key={s}
              className={cx(
                "inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-semibold ring-1",
                SEVERITY_CLASSES[s].counter,
              )}
            >
              <SeverityDot severity={s} />
              {SEVERITY_LABEL[s]} <span className="tabular-nums">{counts[s] ?? 0}</span>
            </li>
          ))}
        </ul>
      )}
    </header>
  );
}

import { useMemo, useState } from "react";
import DocumentsPanel from "./components/DocumentsPanel";
import ReportView from "./components/ReportView";
import RulesPanel from "./components/RulesPanel";
import TopBar from "./components/TopBar";
import { ErrorNote, GlassPanel } from "./components/ui";
import { useDocumentReport } from "./hooks/useDocumentReport";
import { useDocuments } from "./hooks/useDocuments";
import { useRules } from "./hooks/useRules";
import { useRuleTemplates } from "./hooks/useRuleTemplates";
import { countBySeverity } from "./lib/highlight";
import { usesAiQuota } from "./lib/templates";
import type { DocumentSummary } from "./types";

/** Container: wires the data hooks to the presentation components. */
export default function App() {
  const rules = useRules();
  const templates = useRuleTemplates(rules.reload);
  const docs = useDocuments();
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const report = useDocumentReport(selectedId);

  const counts = useMemo(() => (report.violations ? countBySeverity(report.violations) : null), [report.violations]);
  const aiRulesEnabled = rules.rules.filter((r) => r.enabled && usesAiQuota(r)).length;

  async function upload(file: File) {
    const doc = await docs.upload(file);
    if (doc) setSelectedId(doc.id);
  }

  async function removeDocument(doc: DocumentSummary) {
    if ((await docs.remove(doc.id)) && doc.id === selectedId) setSelectedId(null);
  }

  return (
    <div className="flex min-h-screen flex-col bg-linear-to-br from-slate-950 via-slate-900 to-navy-950 lg:h-screen">
      <TopBar documentName={report.document?.filename ?? null} counts={counts} />
      <div className="grid flex-1 gap-4 p-4 sm:p-6 lg:min-h-0 lg:grid-cols-[22rem_minmax(0,1fr)]">
        <aside className="flex flex-col gap-4 lg:min-h-0 lg:overflow-y-auto" aria-label="Rules and documents">
          <RulesPanel
            rules={rules.rules}
            types={rules.types}
            loading={rules.loading}
            error={rules.error}
            onDismissError={rules.dismissError}
            onCreate={rules.createRule}
            onUpdate={rules.updateRule}
            onToggle={rules.toggleRule}
            onDelete={rules.deleteRule}
            templates={{
              templates: templates.templates,
              status: templates.status,
              error: templates.error,
              onRetry: templates.retry,
            }}
            samples={{ ...templates.samples, onLoad: templates.loadSamples, onDismiss: templates.dismissSamples }}
          />
          <DocumentsPanel
            documents={docs.documents}
            selectedId={selectedId}
            loading={docs.loading}
            uploading={docs.uploading}
            error={docs.error}
            onSelect={setSelectedId}
            onUpload={upload}
            onDelete={removeDocument}
          />
        </aside>

        <main className="flex min-w-0 flex-col gap-4 lg:min-h-0">
          {report.error && <ErrorNote>{report.error}</ErrorNote>}
          {report.document ? (
            <ReportView
              key={`${report.document.id}-${report.checkedAt ?? "unchecked"}`}
              document={report.document}
              violations={report.violations}
              checking={report.checking}
              checkedAt={report.checkedAt}
              aiRulesEnabled={aiRulesEnabled}
              onCheck={report.runCheck}
            />
          ) : (
            <GlassPanel className="m-auto max-w-lg p-8 text-sm leading-7 text-slate-700">
              {report.loading ? (
                <p role="status">Loading…</p>
              ) : (
                <ol className="list-decimal space-y-1 pl-5">
                  <li>Create rules on the left, pick a template, or load the sample rules.</li>
                  <li>Upload a .docx document.</li>
                  <li>Click “Check document” to see every violation and where it is.</li>
                </ol>
              )}
            </GlassPanel>
          )}
        </main>
      </div>
    </div>
  );
}

