import { act, fireEvent, render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { FLASH_MS } from "../lib/motion";
import { DOC, violation } from "../test/fixtures";
import type { Violation } from "../types";
import ReportView from "./ReportView";

const scrollIntoView = vi.fn();

beforeEach(() => {
  scrollIntoView.mockClear();
  Element.prototype.scrollIntoView = scrollIntoView;
});

afterEach(() => {
  vi.useRealTimers();
});

const SPAN = violation({ id: "1-0", rule_id: 1, rule_name: "No figures", message: "Reveals range", block_id: 1, start: 23, end: 28 });
const WHOLE = violation({ id: "2-0", rule_id: 2, rule_name: "Cell rule", message: "Bad cell", block_id: 3 }, "medium");
const DOC_LEVEL = violation({ id: "3-0", rule_id: 3, rule_name: "Banner", message: "Missing banner", block_id: null, location: "Whole document" }, "low");

function setup(violations: Violation[] | null = [SPAN, WHOLE, DOC_LEVEL], aiRulesEnabled = 0) {
  const onCheck = vi.fn();
  render(
    <ReportView
      document={DOC}
      violations={violations}
      checking={false}
      checkedAt={null}
      aiRulesEnabled={aiRulesEnabled}
      onCheck={onCheck}
    />,
  );
  return { onCheck };
}

const list = () => screen.getByRole("list", { name: "Violations list" });
const card = (name: RegExp) => within(list()).getByRole("button", { name });
const block = (text: string) => screen.getByText(text).closest("[data-block-id]") as HTMLElement;

describe("ReportView", () => {
  it("highlights the exact span of a violation with its severity", () => {
    setup();
    const mark = screen.getByText("50 km");
    expect(mark.tagName).toBe("MARK");
    expect(mark).toHaveAttribute("data-severity", "high");
    expect(mark).toHaveClass("bg-red-200/90");
    expect(mark).toHaveAttribute("title", "No figures: Reveals range");
  });

  it("flags the whole block when there is no span, inside the table", () => {
    setup();
    const cell = block("2 seconds");
    expect(cell).toHaveAttribute("data-severity", "medium");
    expect(cell.closest("td")).not.toBeNull();
  });

  it("lists document-level violations first, labelled Whole document", () => {
    setup();
    const cards = within(list()).getAllByRole("button");
    expect(cards[0]).toHaveTextContent("Banner");
    expect(cards[0]).toHaveTextContent("Whole document");
    expect(cards[1]).toHaveTextContent("No figures");
  });

  it("scrolls to the paragraph, flashes it for ~1.5 s and keeps it active", async () => {
    vi.useFakeTimers();
    setup();
    fireEvent.click(card(/No figures/));
    expect(scrollIntoView).toHaveBeenCalledWith({ behavior: "smooth", block: "center" });
    const target = block("50 km");
    expect(target).toHaveAttribute("data-flash", "true");
    expect(target).toHaveAttribute("data-active", "true");
    expect(within(target).getByTestId("flash-overlay")).toHaveClass("animate-flash");
    expect(screen.getByText("50 km")).toHaveAttribute("data-active", "true");
    expect(card(/No figures/)).toHaveAttribute("aria-current", "true");

    act(() => vi.advanceTimersByTime(FLASH_MS - 1));
    expect(target).toHaveAttribute("data-flash", "true");
    act(() => vi.advanceTimersByTime(1));
    expect(target).not.toHaveAttribute("data-flash");
    expect(target).toHaveAttribute("data-active", "true");
  });

  it("restarts the flash when the same violation is clicked again", () => {
    vi.useFakeTimers();
    setup();
    fireEvent.click(card(/No figures/));
    const first = screen.getByTestId("flash-overlay");
    act(() => vi.advanceTimersByTime(1000));
    fireEvent.click(card(/No figures/));
    const second = screen.getByTestId("flash-overlay");
    expect(second).not.toBe(first); // remounted => the CSS animation starts over
    act(() => vi.advanceTimersByTime(1000));
    expect(screen.getByTestId("flash-overlay")).toBe(second); // timer was reset
  });

  it("moves the active state and flash when another violation is clicked", () => {
    setup();
    fireEvent.click(card(/No figures/));
    fireEvent.click(card(/Cell rule/));
    expect(block("2 seconds")).toHaveAttribute("data-flash", "true");
    expect(block("50 km")).not.toHaveAttribute("data-flash");
    expect(block("50 km")).not.toHaveAttribute("data-active");
    expect(card(/No figures/)).not.toHaveAttribute("aria-current");
  });

  it("does not scroll or flash for document-level violations", () => {
    setup();
    fireEvent.click(card(/Banner/));
    expect(scrollIntoView).not.toHaveBeenCalled();
    expect(screen.queryByTestId("flash-overlay")).toBeNull();
    expect(card(/Banner/)).toHaveAttribute("aria-current", "true");
  });

  it("clicking a highlight selects its violation and reveals it in the list", async () => {
    setup();
    await userEvent.click(screen.getByText("50 km"));
    expect(card(/No figures/)).toHaveAttribute("aria-current", "true");
    expect(scrollIntoView).toHaveBeenCalledWith({ behavior: "smooth", block: "nearest" });
  });

  it("highlights are keyboard accessible", async () => {
    setup();
    screen.getByText("50 km").focus();
    await userEvent.keyboard("{Enter}");
    expect(card(/No figures/)).toHaveAttribute("aria-current", "true");
  });

  it("filters by severity with counted chips", async () => {
    setup();
    const high = screen.getByRole("button", { name: "High 1" });
    expect(screen.getByRole("button", { name: "Medium 1" })).toHaveAttribute("aria-pressed", "true");
    expect(screen.getByRole("button", { name: "Low 1" })).toBeInTheDocument();

    await userEvent.click(high);
    expect(high).toHaveAttribute("aria-pressed", "false");
    expect(within(list()).queryByRole("button", { name: /No figures/ })).toBeNull();
    // The highlight disappears from the document too
    expect(screen.getByText("50 km").tagName).toBe("SPAN");
  });

  it("filters by rule and updates chip counts", async () => {
    setup();
    await userEvent.selectOptions(screen.getByRole("combobox", { name: "Filter by rule" }), "Cell rule (1)");
    expect(within(list()).getAllByRole("button")).toHaveLength(1);
    expect(screen.getByRole("button", { name: "High 0" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Medium 1" })).toBeInTheDocument();
  });

  it("offers to clear filters when nothing matches", async () => {
    setup();
    for (const name of ["High 1", "Medium 1", "Low 1"]) await userEvent.click(screen.getByRole("button", { name }));
    expect(screen.getByText("No violations match the filters.")).toBeInTheDocument();
    await userEvent.click(screen.getByRole("button", { name: "Clear filters" }));
    expect(within(list()).getAllByRole("button")).toHaveLength(3);
  });

  it("runs a re-check and warns when AI rules will spend quota", async () => {
    const { onCheck } = setup([SPAN], 2);
    expect(screen.getByText(/2 AI rules enabled/)).toBeInTheDocument();
    await userEvent.click(screen.getByRole("button", { name: "Re-check" }));
    expect(onCheck).toHaveBeenCalledOnce();
  });

  it("shows the empty and unchecked states", () => {
    setup([]);
    expect(screen.getByText(/No violations found/)).toBeInTheDocument();
    expect(screen.queryByText(/AI rule/)).toBeNull();
  });

  it("offers the first check when never checked", () => {
    setup(null);
    expect(screen.getByRole("button", { name: "Check document" })).toBeInTheDocument();
    expect(screen.getByText(/Not checked yet\. Click/)).toBeInTheDocument();
  });

  it("keeps dir=auto on document text for RTL documents", () => {
    setup();
    expect(block("50 km")).toHaveAttribute("dir", "auto");
  });
});

import { act, renderHook, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { api, ApiError } from "../api";
import { rule, template } from "../test/fixtures";
import { SAMPLES_UNAVAILABLE, useRuleTemplates } from "./useRuleTemplates";

afterEach(() => {
  vi.restoreAllMocks();
});

describe("useRuleTemplates", () => {
  it("loads the templates", async () => {
    const templates = [template({ id: "pii-all" })];
    vi.spyOn(api, "ruleTemplates").mockResolvedValue(templates);
    const { result } = renderHook(() => useRuleTemplates(vi.fn()));
    expect(result.current.status).toBe("loading");
    await waitFor(() => expect(result.current.status).toBe("ready"));
    expect(result.current.templates).toEqual(templates);
  });

  it.each([404, 405])("marks templates unavailable when the endpoint is missing (%i)", async (status) => {
    vi.spyOn(api, "ruleTemplates").mockRejectedValue(new ApiError(status, "Not Found"));
    const { result } = renderHook(() => useRuleTemplates(vi.fn()));
    await waitFor(() => expect(result.current.status).toBe("unavailable"));
    expect(result.current.error).toBeNull();
    expect(result.current.templates).toEqual([]);
  });

  it("reports a network failure and can retry", async () => {
    const spy = vi.spyOn(api, "ruleTemplates").mockRejectedValueOnce(new TypeError("Failed to fetch"));
    const { result } = renderHook(() => useRuleTemplates(vi.fn()));
    await waitFor(() => expect(result.current.status).toBe("error"));
    expect(result.current.error).toMatch(/^Network error/);

    spy.mockResolvedValueOnce([template({ id: "x" })]);
    act(() => result.current.retry());
    expect(result.current.status).toBe("loading");
    await waitFor(() => expect(result.current.status).toBe("ready"));
    expect(spy).toHaveBeenCalledTimes(2);
  });

  it("loads the sample rules, reports the counts and refreshes the rules", async () => {
    vi.spyOn(api, "ruleTemplates").mockResolvedValue([]);
    vi.spyOn(api, "loadSampleRules").mockResolvedValue({
      created: [rule({ id: 1 }), rule({ id: 2 }), rule({ id: 3 })],
      skipped: ["PII", "Acronyms"],
    });
    const onRulesChanged = vi.fn();
    const { result } = renderHook(() => useRuleTemplates(onRulesChanged));

    await act(() => result.current.loadSamples());
    expect(result.current.samples).toEqual({ loading: false, message: "3 added, 2 already present", error: null });
    expect(onRulesChanged).toHaveBeenCalledOnce();

    act(() => result.current.dismissSamples());
    expect(result.current.samples.message).toBeNull();
  });

  it("explains a missing samples endpoint and does not refresh", async () => {
    vi.spyOn(api, "ruleTemplates").mockResolvedValue([]);
    vi.spyOn(api, "loadSampleRules").mockRejectedValue(new ApiError(404, "Not Found"));
    const onRulesChanged = vi.fn();
    const { result } = renderHook(() => useRuleTemplates(onRulesChanged));
    await act(() => result.current.loadSamples());
    expect(result.current.samples.error).toBe(SAMPLES_UNAVAILABLE);
    expect(onRulesChanged).not.toHaveBeenCalled();
  });

  it("reports other sample-load failures", async () => {
    vi.spyOn(api, "ruleTemplates").mockResolvedValue([]);
    vi.spyOn(api, "loadSampleRules").mockRejectedValue(new TypeError("Failed to fetch"));
    const { result } = renderHook(() => useRuleTemplates(vi.fn()));
    await act(() => result.current.loadSamples());
    expect(result.current.samples.error).toMatch(/^Network error/);
    expect(result.current.samples.loading).toBe(false);
  });
});

import { act, renderHook, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { api, ApiError } from "../api";
import { rule, RULE_TYPES } from "../test/fixtures";
import { useRules } from "./useRules";

afterEach(() => {
  vi.restoreAllMocks();
});

async function loaded() {
  const hook = renderHook(() => useRules());
  await waitFor(() => expect(hook.result.current.loading).toBe(false));
  return hook;
}

describe("useRules", () => {
  it("loads rules and rule types", async () => {
    vi.spyOn(api, "rules").mockResolvedValue([rule({ id: 1 })]);
    vi.spyOn(api, "ruleTypes").mockResolvedValue(RULE_TYPES);
    const { result } = await loaded();
    expect(result.current.rules).toHaveLength(1);
    expect(result.current.types).toEqual(RULE_TYPES);
    expect(result.current.error).toBeNull();
  });

  it("reports a network failure while loading", async () => {
    vi.spyOn(api, "rules").mockRejectedValue(new TypeError("Failed to fetch"));
    vi.spyOn(api, "ruleTypes").mockResolvedValue(RULE_TYPES);
    const { result } = await loaded();
    expect(result.current.error).toMatch(/^Network error/);
  });

  it("creates a rule and refreshes; validation errors are re-thrown to the form", async () => {
    const rules = vi.spyOn(api, "rules").mockResolvedValue([]);
    vi.spyOn(api, "ruleTypes").mockResolvedValue(RULE_TYPES);
    const create = vi.spyOn(api, "createRule").mockResolvedValue(rule({ id: 5 }));
    const { result } = await loaded();

    rules.mockResolvedValue([rule({ id: 5 })]);
    await act(() => result.current.createRule({ name: "R", type: "forbidden_text", params: { pattern: "x" } }));
    expect(create).toHaveBeenCalledOnce();
    expect(result.current.rules.map((r) => r.id)).toEqual([5]);

    create.mockRejectedValue(new ApiError(422, "Invalid regular expression"));
    await expect(result.current.createRule({ name: "R", type: "forbidden_text", params: {} })).rejects.toThrow(
      "Invalid regular expression",
    );
  });

  it("toggles and deletes, reporting failures through error", async () => {
    const r = rule({ id: 2, enabled: true });
    vi.spyOn(api, "rules").mockResolvedValue([r]);
    vi.spyOn(api, "ruleTypes").mockResolvedValue(RULE_TYPES);
    const update = vi.spyOn(api, "updateRule").mockResolvedValue({ ...r, enabled: false });
    const del = vi.spyOn(api, "deleteRule").mockRejectedValue(new ApiError(404, "Rule not found"));
    const { result } = await loaded();

    await act(() => result.current.toggleRule(r));
    expect(update).toHaveBeenCalledWith(2, { enabled: false });

    await act(() => result.current.deleteRule(r));
    expect(del).toHaveBeenCalledWith(2);
    expect(result.current.error).toBe("Rule not found");
    act(() => result.current.dismissError());
    expect(result.current.error).toBeNull();
  });
});

import { act, renderHook, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { api, ApiError } from "../api";
import { DOC, summary } from "../test/fixtures";
import { useDocuments } from "./useDocuments";

afterEach(() => {
  vi.restoreAllMocks();
});

async function loaded() {
  const hook = renderHook(() => useDocuments());
  await waitFor(() => expect(hook.result.current.loading).toBe(false));
  return hook;
}

const file = () => new File(["x"], "spec.docx");

describe("useDocuments", () => {
  it("lists documents", async () => {
    vi.spyOn(api, "documents").mockResolvedValue([summary(1), summary(2)]);
    const { result } = await loaded();
    expect(result.current.documents.map((d) => d.id)).toEqual([1, 2]);
  });

  it("uploads, refreshes and returns the new document", async () => {
    const list = vi.spyOn(api, "documents").mockResolvedValue([]);
    vi.spyOn(api, "uploadDocument").mockResolvedValue(DOC);
    const { result } = await loaded();
    list.mockResolvedValue([summary(1, "spec.docx")]);

    let uploaded: unknown;
    await act(async () => {
      uploaded = await result.current.upload(file());
    });
    expect(uploaded).toEqual(DOC);
    expect(result.current.documents).toHaveLength(1);
    expect(result.current.uploading).toBe(false);
  });

  it("reports an upload error (e.g. not a .docx) and returns null", async () => {
    vi.spyOn(api, "documents").mockResolvedValue([]);
    vi.spyOn(api, "uploadDocument").mockRejectedValue(new ApiError(400, "Only .docx files are supported"));
    const { result } = await loaded();
    let uploaded: unknown;
    await act(async () => {
      uploaded = await result.current.upload(file());
    });
    expect(uploaded).toBeNull();
    expect(result.current.error).toBe("Only .docx files are supported");
  });

  it("deletes a document, and reports a network failure", async () => {
    vi.spyOn(api, "documents").mockResolvedValue([summary(1)]);
    const del = vi.spyOn(api, "deleteDocument").mockResolvedValue(undefined);
    const { result } = await loaded();

    let ok: unknown;
    await act(async () => {
      ok = await result.current.remove(1);
    });
    expect(ok).toBe(true);
    expect(del).toHaveBeenCalledWith(1);

    del.mockRejectedValue(new TypeError("Failed to fetch"));
    await act(async () => {
      ok = await result.current.remove(1);
    });
    expect(ok).toBe(false);
    expect(result.current.error).toMatch(/^Network error/);
  });
});

import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import type { ComponentProps } from "react";
import { describe, expect, it, vi } from "vitest";
import { rule, RULE_TYPES, template } from "../test/fixtures";
import RulesPanel from "./RulesPanel";

type Props = ComponentProps<typeof RulesPanel>;

const TEMPLATES = [
  template({ id: "markings", label: "Classification markings", category: "security" }),
  template({
    id: "ai-perf",
    label: "No performance figures",
    category: "ai",
    rule: { name: "No performance figures", type: "llm", params: { instruction: "No numbers" }, enabled: false },
  }),
];

function setup(overrides: Partial<Props> = {}) {
  const props: Props = {
    rules: [],
    types: RULE_TYPES,
    loading: false,
    error: null,
    onDismissError: vi.fn(),
    onCreate: vi.fn().mockResolvedValue(undefined),
    onUpdate: vi.fn().mockResolvedValue(undefined),
    onToggle: vi.fn(),
    onDelete: vi.fn(),
    templates: { templates: TEMPLATES, status: "ready", error: null, onRetry: vi.fn() },
    samples: { loading: false, message: null, error: null, onLoad: vi.fn(), onDismiss: vi.fn() },
    ...overrides,
  };
  render(<RulesPanel {...props} />);
  return props;
}

describe("RulesPanel", () => {
  it("prefills the new-rule form from a template and creates the (edited) rule", async () => {
    const props = setup();
    await userEvent.click(screen.getByRole("button", { name: "Add from template" }));
    const picker = screen.getByRole("group", { name: "Rule templates" });
    expect(within(picker).getByText("Security")).toBeInTheDocument();
    await userEvent.click(within(picker).getByRole("button", { name: /Classification markings/ }));

    const form = screen.getByRole("form", { name: "New rule" });
    expect(within(form).getByText("From template: Classification markings")).toBeInTheDocument();
    expect(within(form).getByLabelText("Type")).toHaveValue("forbidden_text");
    expect(within(form).getByLabelText("Name")).toHaveValue("No classification markings");
    expect(within(form).getByLabelText("Pattern")).toHaveValue("\\b(TOP SECRET|CONFIDENTIAL)\\b");
    expect(within(form).getByLabelText("Is Regex")).toBeChecked();
    expect(within(form).getByLabelText("Severity")).toHaveValue("medium");

    await userEvent.clear(within(form).getByLabelText("Name"));
    await userEvent.type(within(form).getByLabelText("Name"), "Markings");
    await userEvent.click(within(form).getByRole("button", { name: "Save rule" }));
    expect(props.onCreate).toHaveBeenCalledWith({
      name: "Markings",
      description: "",
      type: "forbidden_text",
      params: { pattern: "\\b(TOP SECRET|CONFIDENTIAL)\\b", is_regex: true, case_sensitive: true },
      severity: "medium",
      enabled: true,
    });
    expect(screen.queryByRole("form")).toBeNull();
  });

  it("keeps AI templates disabled and marks them as using quota", async () => {
    const props = setup();
    await userEvent.click(screen.getByRole("button", { name: "Add from template" }));
    const option = screen.getByRole("button", { name: /No performance figures/ });
    expect(within(option).getByText("AI · uses quota")).toBeInTheDocument();
    await userEvent.click(option);
    const form = screen.getByRole("form", { name: "New rule" });
    expect(within(form).getByLabelText("Enabled")).not.toBeChecked();
    expect(within(form).getByLabelText("Instruction")).toHaveValue("No numbers");
    await userEvent.click(within(form).getByRole("button", { name: "Save rule" }));
    expect(props.onCreate).toHaveBeenCalledWith(expect.objectContaining({ type: "llm", enabled: false }));
  });

  it("shows the server's validation error and keeps the form open", async () => {
    setup({ onCreate: vi.fn().mockRejectedValue(new Error("Invalid regular expression")) });
    await userEvent.click(screen.getByRole("button", { name: "+ New rule" }));
    const form = screen.getByRole("form", { name: "New rule" });
    await userEvent.type(within(form).getByLabelText("Name"), "Bad");
    await userEvent.type(within(form).getByLabelText("Pattern"), "(");
    await userEvent.click(within(form).getByRole("button", { name: "Save rule" }));
    expect(within(form).getByRole("alert")).toHaveTextContent("Invalid regular expression");
  });

  it("hides the template features when the server doesn't have them (404)", () => {
    setup({ templates: { templates: [], status: "unavailable", error: null, onRetry: vi.fn() } });
    expect(screen.queryByRole("button", { name: "Add from template" })).toBeNull();
    expect(screen.queryByRole("button", { name: "Load Sample Rules" })).toBeNull();
    expect(screen.getByText(/not available on this server/)).toBeInTheDocument();
    // Creating rules by hand still works
    expect(screen.getByRole("button", { name: "+ New rule" })).toBeEnabled();
  });

  it("shows a template load error with retry", async () => {
    const onRetry = vi.fn();
    setup({ templates: { templates: [], status: "error", error: "Network error: offline", onRetry } });
    expect(screen.getByRole("alert")).toHaveTextContent("Could not load rule templates: Network error: offline");
    await userEvent.click(screen.getByRole("button", { name: "Retry" }));
    expect(onRetry).toHaveBeenCalledOnce();
  });

  it("loads the sample rules and shows the result", async () => {
    const onLoad = vi.fn();
    setup({ samples: { loading: false, message: "4 added, 2 already present", error: null, onLoad, onDismiss: vi.fn() } });
    await userEvent.click(screen.getByRole("button", { name: "Load Sample Rules" }));
    expect(onLoad).toHaveBeenCalledOnce();
    expect(screen.getByRole("status")).toHaveTextContent("Sample rules: 4 added, 2 already present");
  });

  it("shows a sample-load error", () => {
    setup({ samples: { loading: false, message: null, error: "Sample rules are not available on this server.", onLoad: vi.fn(), onDismiss: vi.fn() } });
    expect(screen.getByRole("alert")).toHaveTextContent("Sample rules are not available");
  });

  it("lists rules with AI badge, toggle, edit and delete", async () => {
    const ai = rule({ id: 1, name: "AI check", type: "llm", params: { instruction: "No numbers" }, enabled: false });
    const plain = rule({ id: 2, name: "Plain" });
    const props = setup({ rules: [ai, plain] });

    const list = screen.getByRole("list", { name: "Rules list" });
    const [aiRow, plainRow] = within(list).getAllByRole("listitem");
    expect(within(aiRow).getByText("AI · uses quota")).toBeInTheDocument();
    expect(within(plainRow).queryByText("AI · uses quota")).toBeNull();

    await userEvent.click(screen.getByRole("switch", { name: "Enable Plain" }));
    expect(props.onToggle).toHaveBeenCalledWith(plain);
    await userEvent.click(screen.getByRole("button", { name: "Delete Plain" }));
