import { Document, HeadingLevel, Packer, Paragraph, Table, TableCell, TableRow } from "docx";

/**
 * Builds a tiny .docx at test time (no binary fixture in git): a heading, two paragraphs and a 2x2 table.
 * `marker` makes the text unique per test run so assertions never match another run's document.
 */
export async function buildDocx(marker: string): Promise<Buffer> {
  const cell = (text: string) => new TableCell({ children: [new Paragraph(text)] });
  const doc = new Document({
    sections: [
      {
        children: [
          new Paragraph({ text: "Performance", heading: HeadingLevel.HEADING_1 }),
          new Paragraph(`Intro paragraph for run ${marker}. Nothing to flag here.`),
          new Paragraph(`The detection range is ${marker} km in clear weather.`),
          new Table({
            rows: [
              new TableRow({ children: [cell("Parameter"), cell("Value")] }),
              new TableRow({ children: [cell("Latency"), cell("2 seconds")] }),
            ],
          }),
        ],
      },
    ],
  });
  return Packer.toBuffer(doc);
}

import { expect, type APIRequestContext } from "@playwright/test";

interface ApiRule {
  id: number;
  name: string;
  type: string;
  enabled: boolean;
}

interface ApiDocument {
  id: number;
  filename: string;
}

/**
 * Hard safety stop before any "Check document" click: the check runs every enabled rule,
 * and an enabled `llm` rule would call the real Gemini API and spend quota.
 */
export async function assertNoEnabledLlmRules(request: APIRequestContext): Promise<void> {
  const res = await request.get("/api/rules");
  expect(res.ok()).toBe(true);
  const rules = (await res.json()) as ApiRule[];
  const llm = rules.filter((r) => r.type === "llm" && r.enabled).map((r) => r.name);
  expect(llm, "enabled llm rules would call the real LLM API; refusing to run a check").toEqual([]);
}

/** Deletes the rules and documents a test created (matched by its unique marker). */
export async function cleanUp(request: APIRequestContext, marker: string): Promise<void> {
  const rules = (await (await request.get("/api/rules")).json()) as ApiRule[];
  for (const r of rules.filter((r) => r.name.includes(marker))) await request.delete(`/api/rules/${r.id}`);
  const docs = (await (await request.get("/api/documents")).json()) as ApiDocument[];
  for (const d of docs.filter((d) => d.filename.includes(marker))) await request.delete(`/api/documents/${d.id}`);
}

/** Unique, regex-safe token per test, e.g. "RGE2EM1ABC2". */
export function uniqueMarker(): string {
  return `RGE2E${Date.now().toString(36).toUpperCase()}${Math.floor(Math.random() * 1000)}`;
}

/** The template endpoints are built on another branch; an older server answers 404 (or 405, see api.ts). */
export async function templatesAvailable(request: APIRequestContext): Promise<{ ok: boolean; status: number }> {
  const res = await request.get("/api/rules/templates");
  return { ok: res.ok(), status: res.status() };
}

export const DOCX_MIME = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

import { expect, test, type Page } from "@playwright/test";
import { buildDocx } from "./docx";
import { assertNoEnabledLlmRules, cleanUp, DOCX_MIME, uniqueMarker } from "./helpers";

// Non-LLM rules only (forbidden_text): these tests never reach the Gemini API.

let marker = "";

test.beforeEach(() => {
  marker = uniqueMarker();
});

test.afterEach(async ({ request }) => {
  await cleanUp(request, marker);
});

async function createForbiddenTextRule(page: Page, name: string, pattern: string) {
  await page.getByRole("button", { name: "+ New rule" }).click();
  const form = page.getByRole("form", { name: "New rule" });
  await form.getByLabel("Type").selectOption("forbidden_text");
  await form.getByLabel("Name").fill(name);
  await form.getByLabel("Pattern").fill(pattern);
  await form.getByLabel("Severity").selectOption("high");
  await form.getByRole("button", { name: "Save rule" }).click();
  await expect(form).toBeHidden();
  await expect(page.getByRole("list", { name: "Rules list" }).getByText(name)).toBeVisible();
}

async function uploadAndCheck(page: Page, request: Parameters<typeof assertNoEnabledLlmRules>[0]) {
  await page.getByTestId("upload-input").setInputFiles({
    name: `${marker}.docx`,
    mimeType: DOCX_MIME,
    buffer: await buildDocx(marker),
  });
  await expect(page.getByRole("heading", { name: `${marker}.docx` })).toBeVisible();
  await expect(page.getByText(`The detection range is ${marker} km`)).toBeVisible();

  await assertNoEnabledLlmRules(request);
  await page.getByRole("button", { name: "Check document" }).click();
}

test("create a rule, upload, check, then jump from a violation to its paragraph", async ({ page, request }) => {
  const ruleName = `No ${marker}`;
  await page.goto("/");
  await expect(page.getByRole("heading", { name: "Ruleguarder" })).toBeVisible();

  await createForbiddenTextRule(page, ruleName, marker);
  await uploadAndCheck(page, request);

  // The exact span is highlighted with the rule's severity
  const mark = page.locator("mark[data-violation]", { hasText: marker });
  await expect(mark).toBeVisible();
  await expect(mark).toHaveAttribute("data-severity", "high");
  await expect(page.getByRole("list", { name: "Violations by severity" })).toContainText("High");

  // Clicking the violation scrolls to the paragraph, flashes it (~1.5 s) and keeps it active
  const card = page.getByRole("list", { name: "Violations list" }).getByRole("button", { name: new RegExp(ruleName) });
  await card.click();
  const paragraph = page.locator("[data-block-id]", { has: mark });
  await expect(paragraph).toHaveAttribute("data-flash", "true");
  await expect(paragraph).toHaveAttribute("data-active", "true");
  await expect(paragraph).toBeInViewport();
  await expect(card).toHaveAttribute("aria-current", "true");

  await expect(paragraph).not.toHaveAttribute("data-flash", "true", { timeout: 5_000 });
  await expect(paragraph).toHaveAttribute("data-active", "true");
});

test("clicking a highlight selects its violation; severity chips filter", async ({ page, request }) => {
  const ruleName = `Flag ${marker}`;
  await page.goto("/");
  await createForbiddenTextRule(page, ruleName, marker);
  await uploadAndCheck(page, request);

  const mark = page.locator("mark[data-violation]", { hasText: marker });
  await mark.click();
  const card = page.getByRole("list", { name: "Violations list" }).getByRole("button", { name: new RegExp(ruleName) });
  await expect(card).toHaveAttribute("aria-current", "true");

  const highChip = page.getByRole("group", { name: "Filter by severity" }).getByRole("button", { name: /^High \d+$/ });
  await highChip.click();
  await expect(highChip).toHaveAttribute("aria-pressed", "false");
  await expect(card).toBeHidden();
  await expect(mark).toBeHidden();
  await highChip.click();
  await expect(card).toBeVisible();
});

import { expect, test } from "@playwright/test";
import { assertNoEnabledLlmRules, templatesAvailable } from "./helpers";

interface ApiTemplate {
  id: string;
  label: string;
  rule: { name: string; type: string };
}

// No test here ever clicks "Check document", so no LLM call is possible.

test.describe("with the template endpoints", () => {
  test.beforeEach(async ({ request }) => {
    const { ok, status } = await templatesAvailable(request);
    test.skip(!ok, `GET /api/rules/templates returned ${status}: template endpoints not on this server`);
  });

  test("Add from template prefills the new-rule form", async ({ page, request }) => {
    const templates = (await (await request.get("/api/rules/templates")).json()) as ApiTemplate[];
    const pick = templates.find((t) => t.rule.type !== "llm");
    test.skip(!pick, "no non-LLM template to pick");
    if (!pick) return;

    await page.goto("/");
    await page.getByRole("button", { name: "Add from template" }).click();
    await page.getByRole("group", { name: "Rule templates" }).getByRole("button", { name: new RegExp(pick.label) }).click();
    const form = page.getByRole("form", { name: "New rule" });
    await expect(form.getByText(`From template: ${pick.label}`)).toBeVisible();
    await expect(form.getByLabel("Name")).toHaveValue(pick.rule.name);
    await expect(form.getByLabel("Type")).toHaveValue(pick.rule.type);
    await form.getByRole("button", { name: "Cancel" }).click();
    await expect(form).toBeHidden();
  });

  test("Load Sample Rules reports what was added and keeps AI rules disabled", async ({ page, request }) => {
    await page.goto("/");
    await page.getByRole("button", { name: "Load Sample Rules" }).click();
    await expect(page.getByRole("status").filter({ hasText: "Sample rules:" })).toHaveText(
      /Sample rules: \d+ added, \d+ already present/,
    );
    // Contract: the sample AI rule is created disabled
    await assertNoEnabledLlmRules(request);
  });
});

test("without the template endpoints the UI hides the template features", async ({ page, request }) => {
  const { ok, status } = await templatesAvailable(request);
  test.skip(ok, "template endpoints exist on this server");
  expect([404, 405]).toContain(status);

  await page.goto("/");
  await expect(page.getByText("Rule templates and sample rules are not available on this server.")).toBeVisible();
  await expect(page.getByRole("button", { name: "Add from template" })).toHaveCount(0);
  await expect(page.getByRole("button", { name: "Load Sample Rules" })).toHaveCount(0);
  await expect(page.getByRole("button", { name: "+ New rule" })).toBeEnabled();
});

